class Settings(BaseSettings):
    model_config = SettingsConfigDict(secrets_dir="/run/secrets", extra="ignore")
    database_host: str = "localhost"     # outside Docker
    db_password: SecretStr               # /run/secrets/db_password
    def url(self) -> URL:
        return URL.create("postgresql+psycopg", username="app",
                          password=self.db_password.get_secret_value().strip(),
                          host=self.database_host, port=5432, database="rag")
